struct vec { int *buf; size_t len, cap; };

bool vec_shrink_to_fit(struct vec *v)
{
    if (v->cap == v->len) return true;            /* already tight */
    if (v->len == 0) { free(v->buf); v->buf = NULL; v->cap = 0; return true; }
    int *p = realloc(v->buf, v->len * sizeof *p); /* temp: realloc may fail */
    if (!p) return false;                         /* old block still valid */
    v->buf = p; v->cap = v->len;
    return true;
}
